document.addEventListener("alpine:init",()=>{Alpine.data("rccart",()=>({items:[],init(){RockCommerce.addComponent(this)},ready(){console.log("Cart ready")},addItem(product){while(product.amount>0){this.items.push(new CartItem(product.pid,1,product.getVariationString(!0)));product.amount--}},get count(){return this.items.length},}));class CartItem{constructor(pid,amount,variation){this.pid=pid;this.amount=amount;this.variation=variation}}})